<?php
declare(strict_types=1);

$runtimeRoot = null;
foreach ([dirname(__DIR__), dirname(__DIR__, 2)] as $candidate) if (is_file($candidate . '/runtime-guard.php')) { $runtimeRoot = $candidate; break; }
if ($runtimeRoot === null) { http_response_code(500); exit('LirisQ runtime guard is unavailable.'); }
require_once $runtimeRoot . '/runtime-guard.php';
lirisq_require_secure_php();

function applyReply(int $status, array $body): never { http_response_code($status); header('content-type: application/json; charset=utf-8'); header('cache-control: no-store'); exit(json_encode($body, JSON_UNESCAPED_SLASHES)); }
function applyConfig(string $root): array { $value = is_file($root . '/private/lirisq-hosted-config.php') ? require $root . '/private/lirisq-hosted-config.php' : null; if (!is_array($value) || empty($value['database'])) applyReply(503, ['error'=>'Hosted LirisQ configuration is unavailable']); return $value; }
function applyVersion(string $value): array { if (!preg_match('/^(\d+)\.(\d+)\.(\d+)$/', $value, $match)) throw new RuntimeException('Invalid release version'); return [(int)$match[1],(int)$match[2],(int)$match[3]]; }
function applyCompare(string $left, string $right): int { $a=applyVersion($left);$b=applyVersion($right);for($i=0;$i<3;$i++)if($a[$i]!==$b[$i])return $a[$i]<=>$b[$i];return 0; }
function applyStreamer(): void { if (session_status() !== PHP_SESSION_ACTIVE) session_start(['cookie_httponly'=>true,'cookie_secure'=>true,'cookie_samesite'=>'Lax']); if (($_SESSION['lirisq_role'] ?? '') !== 'streamer') applyReply(403,['error'=>'Streamer authentication is required to install updates']); }
function applyOrigin(array $config): void { $origin=$_SERVER['HTTP_ORIGIN']??''; if ($origin !== '' && !hash_equals((string)$config['app_origin'],$origin)) applyReply(403,['error'=>'Cross-origin update request denied']); }
function applyChannel(): string { $body=json_decode((string)file_get_contents('php://input'),true); $channel=is_array($body)?(string)($body['channel']??''):''; if(!in_array($channel,['development','beta','public'],true)) throw new RuntimeException('Choose a valid update channel'); return $channel; }
function applyManifestData(mixed $data): array { if(!is_array($data)||($data['schema']??'')!=='lirisq-distribution/v1'||($data['product']??'')!=='LirisQ'||!is_array($data['releaseNotes']??null)) throw new RuntimeException('Invalid update manifest'); return $data; }
function applyManifest(string $path): array { return applyManifestData(is_file($path)?json_decode((string)file_get_contents($path),true):null); }
function applyDistributionManifestUrl(string $channel): string { return $channel==='beta'?'https://raw.githubusercontent.com/moonscythe/LirisQ-distribution/beta/latest/manifest.json':'https://raw.githubusercontent.com/moonscythe/LirisQ-distribution/main/latest/manifest.json'; }
function applyDistributionFetch(string $url, int $limit, string $channel): string { $branch=$channel==='beta'?'beta':'main'; $prefix='https://raw.githubusercontent.com/moonscythe/LirisQ-distribution/'.$branch.'/'; if(!str_starts_with($url,$prefix))throw new RuntimeException('Distribution update source is not approved');if(!function_exists('curl_init'))throw new RuntimeException('PHP cURL is required for distribution updates');$curl=curl_init($url);curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_FAILONERROR=>true,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>60]);$bytes=curl_exec($curl);$status=(int)curl_getinfo($curl,CURLINFO_RESPONSE_CODE);$error=curl_error($curl);curl_close($curl);if(!is_string($bytes)||$status<200||$status>=300)throw new RuntimeException('Approved distribution update source is unavailable'.($error!==''?': '.$error:''));if(strlen($bytes)>$limit)throw new RuntimeException('Update response exceeds the allowed size');return $bytes; }
function applyArtifact(array $release, string $from, string $root, string $channel): array { $delta=null; foreach (($release['deltas']??[]) as $item) if (($item['from']??null)===$from) $delta=$item; $item=$delta??($release['full']??null); if(!is_array($item)||!preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]*\.zip$/',(string)($item['file']??''))||!preg_match('/^sha256:[a-f0-9]{64}$/i',(string)($item['sha256']??''))) throw new RuntimeException("No verified package path from $from to {$release['version']}"); $path=$root.'/artifacts/'.$item['file']; if(in_array($channel,['beta','public'],true)){if(!is_dir(dirname($path))&&!mkdir(dirname($path),0700,true))throw new RuntimeException('Unable to prepare the distribution update cache');if(file_put_contents($path,applyDistributionFetch((string)($item['url']??''),100*1024*1024,$channel))===false)throw new RuntimeException('Unable to stage the distribution update artifact');} if(!is_file($path)||!hash_equals(strtolower(substr((string)$item['sha256'],7)),hash_file('sha256',$path))) throw new RuntimeException('Artifact checksum verification failed'); return [$path,$delta?'delta':'full']; }
function applyArchive(string $zipPath, string $staging): void { if(!class_exists('ZipArchive')) throw new RuntimeException('PHP ZipArchive is required for server updates'); $zip=new ZipArchive(); if($zip->open($zipPath)!==true) throw new RuntimeException('Unable to open update archive'); for($i=0;$i<$zip->numFiles;$i++){ $name=$zip->getNameIndex($i); $safe=is_string($name)?str_replace('\\','/',$name):''; if($safe===''||str_contains($safe,'..')||str_starts_with($safe,'/')||(!str_starts_with($safe,'public/')&&!str_starts_with($safe,'migrations/'))){ $zip->close(); throw new RuntimeException('Update archive contains an unsafe path'); }} if(!$zip->extractTo($staging)){ $zip->close(); throw new RuntimeException('Unable to stage update archive'); } $zip->close(); }
function applyStagedFiles(string $staging, string $webRoot, string $backup): void { $source=$staging.'/public'; if(!is_dir($source)) throw new RuntimeException('Update archive has no public payload'); $iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($source,FilesystemIterator::SKIP_DOTS)); $written=[]; try { foreach($iterator as $file){ if(!$file->isFile())continue; $relative=substr($file->getPathname(),strlen($source)+1); $target=$webRoot.'/'.$relative; $targetDir=dirname($target); if(!is_dir($targetDir)&&!mkdir($targetDir,0755,true))throw new RuntimeException('Unable to create update directory'); $backupTarget=$backup.'/'.$relative; if(is_file($target)){ if(!is_dir(dirname($backupTarget)))mkdir(dirname($backupTarget),0700,true); if(!copy($target,$backupTarget))throw new RuntimeException('Unable to back up live file'); } if(!copy($file->getPathname(),$target))throw new RuntimeException('Unable to replace live file'); $written[]=$relative; }} catch(Throwable $error){ foreach(array_reverse($written) as $relative){$old=$backup.'/'.$relative;$target=$webRoot.'/'.$relative;if(is_file($old))copy($old,$target);else @unlink($target);} throw $error; } }
function applyMigrations(PDO $pdo, array $release, string $root): void { foreach(($release['migrations']??[]) as $migration){ if(!is_array($migration)||!preg_match('/^[A-Za-z0-9._-]{1,160}$/',(string)($migration['id']??''))||!preg_match('/^[A-Za-z0-9._-]+\.sql$/',(string)($migration['file']??''))||!preg_match('/^sha256:[a-f0-9]{64}$/i',(string)($migration['sha256']??'')))throw new RuntimeException('Invalid packaged migration'); $exists=$pdo->prepare('SELECT 1 FROM lirisq_release_migration WHERE migration_id=?');$exists->execute([$migration['id']]);if($exists->fetchColumn())continue;$path=$root.'/migrations/'.$migration['file'];if(!is_file($path)||!hash_equals(strtolower(substr((string)$migration['sha256'],7)),hash_file('sha256',$path)))throw new RuntimeException('Migration checksum verification failed');$sql=trim((string)file_get_contents($path));if($sql===''||str_contains($sql,'--')||preg_match('/\b(DROP|TRUNCATE|GRANT|REVOKE|LOAD\s+DATA)\b/i',$sql))throw new RuntimeException('Unsafe migration rejected');$statements=array_filter(array_map('trim',explode(';',$sql)));$ddl=(bool)preg_match('/\b(CREATE|ALTER|RENAME)\b/i',$sql);if(!$ddl)$pdo->beginTransaction();try{foreach($statements as $statement)$pdo->exec($statement);$record=$pdo->prepare('INSERT INTO lirisq_release_migration (migration_id,release_version) VALUES (?,?)');$record->execute([$migration['id'],$release['version']]);if(!$ddl&&$pdo->inTransaction())$pdo->commit();}catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}}}

$config=applyConfig($runtimeRoot); $pdo=new PDO($config['database']['dsn'],$config['database']['username'],$config['database']['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); applyStreamer();
$pdo->exec('CREATE TABLE IF NOT EXISTS lirisq_release_installation (singleton TINYINT UNSIGNED NOT NULL PRIMARY KEY, version VARCHAR(32) NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'); $pdo->exec('CREATE TABLE IF NOT EXISTS lirisq_release_migration (migration_id VARCHAR(160) NOT NULL PRIMARY KEY, release_version VARCHAR(32) NOT NULL, applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
$private=$runtimeRoot.'/private/development-updates'; $installed=(string)($pdo->query('SELECT version FROM lirisq_release_installation WHERE singleton=1')->fetchColumn() ?: '0.0.0');
if($_SERVER['REQUEST_METHOD']==='GET') applyReply(200,['installedVersion'=>$installed,'manifestPresent'=>is_file($private.'/manifest.json')]);
try { $channel=applyChannel(); $private=$runtimeRoot.'/private/'.$channel.'-updates'; applyOrigin($config); $manifest=in_array($channel,['beta','public'],true)?applyManifestData(json_decode(applyDistributionFetch(applyDistributionManifestUrl($channel),1024*1024,$channel),true)):applyManifest($private.'/manifest.json'); $releases=array_values(array_filter($manifest['releaseNotes'],fn($r)=>is_array($r)&&isset($r['version'])&&applyCompare((string)$r['version'],$installed)>0)); usort($releases,fn($a,$b)=>applyCompare((string)$a['version'],(string)$b['version'])); if(!$releases)applyReply(200,['updated'=>false,'version'=>$installed,'channel'=>$channel]);
$webRoot=dirname(__DIR__); $staging=$private.'/staging/'.bin2hex(random_bytes(10)); $backup=$private.'/backups/'.date('YmdHis').'-'.bin2hex(random_bytes(4)); if(!mkdir($staging,0700,true)||!mkdir($backup,0700,true))applyReply(500,['error'=>'Unable to create protected update staging area']);
 $cursor=$installed; foreach($releases as $release){ [$artifact] = applyArtifact($release,$cursor,$private,$channel); applyArchive($artifact,$staging); applyMigrations($pdo,$release,$staging); $cursor=(string)$release['version']; } applyStagedFiles($staging,$webRoot,$backup); $stmt=$pdo->prepare('INSERT INTO lirisq_release_installation (singleton,version) VALUES (1,?) ON DUPLICATE KEY UPDATE version=VALUES(version)');$stmt->execute([$cursor]); applyReply(200,['updated'=>true,'version'=>$cursor,'channel'=>$channel,'backup'=>basename($backup)]); } catch(Throwable $error){ applyReply(409,['error'=>$error->getMessage(),'installedVersion'=>$installed]); }
